"use client";

import { useState } from "react";
import { AutoPanPanel } from "@/components/audio-ui/devices/auto-pan/panel";
import { useDeviceLoop } from "@/hooks/use-device-loop";
import { useMasterBus } from "@/hooks/use-master-bus";
import {
  type AutoPanState,
  autoPanDevice,
} from "@/components/audio-ui/devices/auto-pan/device";
import { createAutoPanEngine } from "@/components/audio-ui/devices/auto-pan/engine";

const MASTER_VOLUME = 0.7;
/** Sways on the half note: one cycle every two beats of the loop. */
const START = { division: "1/2", sync: true };

/**
 * An auto pan you can plug in: its state, a panel that draws the movement and an engine that plays it, each its own file. Play the loop, pick a waveform and switch to tremolo.
 */
export function BlockAutoPan() {
  const [state, setState] = useState<AutoPanState>(
    () => autoPanDevice.apply(autoPanDevice.defaults(), START).state
  );
  const master = useMasterBus(MASTER_VOLUME);
  const { tempo } = useDeviceLoop({
    create: createAutoPanEngine,
    destination: master,
    state,
  });
  return (
    <div className="rounded-xl h-full w-full min-w-0">
      <AutoPanPanel onValueChange={setState} tempo={tempo} value={state} />
    </div>
  );
}
